#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""生成严格符合契约的 rule.json，避免在 Shell 或手动字符串拼接中产生转义灾难。"""

import json
from pathlib import Path

# 1. lazy 脚本函数模板
# 选集点击后在 PC 运行库中求值
LAZY_SCRIPT_SOURCE = """(() => {
  var defaultBase = 'http://127.0.0.1:18002';
  var bridgeBase = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : defaultBase;
  var targetUrl = (typeof input !== 'undefined' && input) ? input : '';
  if (!targetUrl) {
    throw new Error('缺少播放目标参数 input');
  }
  var playApi = targetUrl.replace(/^http:\\/\\/[^\\/]+/, bridgeBase);
  var res = request(playApi, { headers: { 'Accept': 'application/json' } });
  var json = typeof res === 'string' ? JSON.parse(res) : res;
  if (!json || json.ok === false) {
    throw new Error((json && json.error) ? json.error : '播放解析失败');
  }
  var playData = json.data || json;
  var defIdx = playData.default || 0;
  var list = playData.list || [];
  if (!list.length || !list[defIdx]) {
    throw new Error('未获取到有效播放流列表');
  }
  var variant = list[defIdx];
  var playUrl = variant.url;
  if (!playUrl) {
    throw new Error('播放流地址为空');
  }
  var headers = variant.headers || {};
  var headerPairs = [];
  for (var k in headers) {
    if (Object.prototype.hasOwnProperty.call(headers, k) && headers[k]) {
      headerPairs.push(k + '@' + headers[k]);
    }
  }
  if (headerPairs.length > 0) {
    playUrl += ';{' + headerPairs.join('&&') + '}';
  }
  return playUrl;
})()"""

# 2. find_rule (一级分类列表)
FIND_RULE_SOURCE = """js:
var d = [];
var defaultBase = 'http://127.0.0.1:18002';
var bridgeBase = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : defaultBase;
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : '';
var targetUrl = '';
if (currentUrl) {
  targetUrl = currentUrl.replace(/^http:\\/\\/[^\\/]+/, bridgeBase);
} else {
  var ch = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && (MY_PARAMS.class || MY_PARAMS.fyclass)) ? (MY_PARAMS.class || MY_PARAMS.fyclass) : '20';
  var pg = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : 1;
  targetUrl = bridgeBase + '/list?channel=' + ch + '&page=' + pg;
}

var res = request(targetUrl, { headers: { 'Accept': 'application/json' } });
var json = typeof res === 'string' ? JSON.parse(res) : res;
if (!json || json.ok === false) {
  throw new Error((json && json.error) ? json.error : '获取列表失败: ' + targetUrl);
}
var data = json.data || json;
var items = data.items || [];
for (var i = 0; i < items.length; i++) {
  var item = items[i];
  var title = item.name || item.title || '';
  var id = item.id;
  if (title && id) {
    d.push({
      title: title,
      desc: item.continu ? String(item.continu) : (item.type ? String(item.type) : ''),
      pic_url: item.pic || '',
      url: bridgeBase + '/detail?id=' + id,
      col_type: 'movie_3'
    });
  }
}
setResult(d);"""

# 3. searchFind (搜索页面)
SEARCH_FIND_SOURCE = """js:
var d = [];
var defaultBase = 'http://127.0.0.1:18002';
var bridgeBase = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : defaultBase;
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : '';
var targetUrl = '';
if (currentUrl) {
  targetUrl = currentUrl.replace(/^http:\\/\\/[^\\/]+/, bridgeBase);
} else {
  var kw = (typeof KEYWORD !== 'undefined' && KEYWORD) ? KEYWORD : ((typeof MY_KEYWORD !== 'undefined' && MY_KEYWORD) ? MY_KEYWORD : '');
  var pg = (typeof MY_PAGE !== 'undefined' && MY_PAGE) ? MY_PAGE : 1;
  targetUrl = bridgeBase + '/search?key=' + encodeURIComponent(kw) + '&page=' + pg;
}

var res = request(targetUrl, { headers: { 'Accept': 'application/json' } });
var json = typeof res === 'string' ? JSON.parse(res) : res;
if (!json || json.ok === false) {
  throw new Error((json && json.error) ? json.error : '搜索请求失败: ' + targetUrl);
}
var data = json.data || json;
var items = data.items || [];
for (var i = 0; i < items.length; i++) {
  var item = items[i];
  var title = item.name || item.title || '';
  var id = item.id;
  if (title && id) {
    d.push({
      title: title,
      desc: item.continu ? String(item.continu) : (item.type ? String(item.type) : ''),
      pic_url: item.pic || '',
      url: bridgeBase + '/detail?id=' + id,
      col_type: 'movie_3'
    });
  }
}
setResult(d);"""

# 4. detail_find_rule (二级详情与选集)
# 注意：选集 URL 格式为：base + '/play?id=' + id + '&part=' + part + '&play=' + play + '@lazyRule=.js:' + LAZY_BODY
DETAIL_FIND_RULE_SOURCE = f"""js:
var d = [];
var defaultBase = 'http://127.0.0.1:18002';
var bridgeBase = (typeof MY_PARAMS !== 'undefined' && MY_PARAMS && MY_PARAMS.bridgeBase) ? MY_PARAMS.bridgeBase : defaultBase;
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
if (!currentUrl) {{
  throw new Error('未获取到详情请求地址');
}}
var targetUrl = currentUrl.replace(/^http:\\/\\/[^\\/]+/, bridgeBase);
var idMatch = targetUrl.match(/[?&]id=([^&#]+)/);
var vid = idMatch ? idMatch[1] : '';
if (!vid) {{
  throw new Error('无法从详情 URL 解析出 id: ' + targetUrl);
}}

var res = request(targetUrl, {{ headers: {{ 'Accept': 'application/json' }} }});
var json = typeof res === 'string' ? JSON.parse(res) : res;
if (!json || json.ok === false) {{
  throw new Error((json && json.error) ? json.error : '获取详情失败: ' + targetUrl);
}}
var detail = json.data || json;
var cleanTitle = detail.name || detail.title || '未知影片';

// 铁律 5: 详情首卡必须显式注入 title: '剧名：' + cleanTitle
d.push({{
  title: '剧名：' + cleanTitle,
  desc: (detail.continu ? ('状态：' + detail.continu + '\\n') : '') + (detail.content ? detail.content : ''),
  pic_url: detail.pic || '',
  url: targetUrl,
  col_type: 'pic_1_card'
}});

var parts = detail.parts || [];
var lazyCode = {json.dumps(LAZY_SCRIPT_SOURCE)};

for (var p = 0; p < parts.length; p++) {{
  var grp = parts[p];
  var lineName = grp.play_zh || grp.play || ('线路 ' + (p + 1));
  d.push({{
    title: '【' + lineName + '】',
    col_type: 'text_1'
  }});
  var episodes = grp.part || [];
  for (var e = 0; e < episodes.length; e++) {{
    var ep = episodes[e];
    var playApiUrl = bridgeBase + '/play?id=' + encodeURIComponent(vid) + '&part=' + encodeURIComponent(ep) + '&play=' + encodeURIComponent(grp.play || '');
    d.push({{
      title: ep,
      url: playApiUrl + '@lazyRule=.js:' + lazyCode,
      col_type: 'text_3'
    }});
  }}
}}

setResult(d);"""

def build_rule():
    rule = {
        "title": "动漫共和国",
        "author": "MoZhi",
        "version": 1,
        "url": "http://127.0.0.1:18002/list?[REDACTED_QUERY]",
        "col_type": "movie_3",
        "class_name": "日漫&国漫&剧场&美漫&特摄&少儿&动态漫&猜你想看",
        "class_url": "20&21&22&23&25&32&26&27",
        "find_rule": FIND_RULE_SOURCE,
        "search_url": "http://127.0.0.1:18002/search?[REDACTED_QUERY]",
        "searchFind": SEARCH_FIND_SOURCE,
        "detail_col_type": "movie_1_vertical_pic",
        "detail_find_rule": DETAIL_FIND_RULE_SOURCE
    }
    return rule

if __name__ == "__main__":
    rule_data = build_rule()
    out_path = Path("rule.json")
    out_path.write_text(json.dumps(rule_data, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"成功生成 rule.json，字节数: {out_path.stat().st_size}")

